/**
 * useHgvTollReport contract — mirrors useGeocodeSearch.test.ts's pattern.
 * Do not edit this file to make it pass — edit useHgvTollReport.ts.
 *
 * Run (Windows, per WORKING_RULES "npm install/ci/build Windows'ta koşulur"):
 *   npm test -- useHgvTollReport --watchAll=false
 */
import { renderHook, waitFor } from "@testing-library/react";
import { useHgvTollReport, HgvTollGroupBy } from "./useHgvTollReport";

let mockToken: string | null = "test-jwt";
jest.mock("store/useAuthStore", () => ({
  useAuthStore: (selector: (s: { token: string | null }) => unknown) => selector({ token: mockToken }),
}));

function mockFetchOnce(body: unknown, ok = true, status = 200) {
  (global.fetch as jest.Mock).mockResolvedValueOnce({
    ok,
    status,
    json: async () => body,
    text: async () => JSON.stringify(body),
  });
}

const REPORT = {
  period: { from: "2026-07-01", to: "2026-07-31" },
  total_toll_eur: 1245.3,
  total_km: 5012,
  avg_eur_per_km: 0.2484,
  groupBy: "vehicle",
  breakdown: [
    { key: "v1", label: "GV-082-B", total_toll_eur: 1245.3, total_km: 5012, task_count: 12, unmatched_count: 0 },
  ],
};

beforeEach(() => {
  global.fetch = jest.fn();
  mockToken = "test-jwt";
});

afterEach(() => {
  jest.clearAllMocks();
});

test("with from/to, requests the real hgv-toll endpoint with the right query params", async () => {
  mockFetchOnce(REPORT);
  renderHook(() => useHgvTollReport("2026-07-01", "2026-07-31", "vehicle"));
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  const [url, init] = (global.fetch as jest.Mock).mock.calls[0];
  const parsed = new URL(String(url));
  expect(parsed.pathname).toBe("/api/dispatcher/reports/hgv-toll");
  expect(parsed.searchParams.get("from")).toBe("2026-07-01");
  expect(parsed.searchParams.get("to")).toBe("2026-07-31");
  expect(parsed.searchParams.get("groupBy")).toBe("vehicle");
  expect((init as RequestInit).headers).toMatchObject({ Authorization: "Bearer test-jwt" });
});

test("defaults groupBy to 'vehicle' when omitted", async () => {
  mockFetchOnce(REPORT);
  renderHook(() => useHgvTollReport("2026-07-01", "2026-07-31"));
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));
  const [url] = (global.fetch as jest.Mock).mock.calls[0];
  expect(new URL(String(url)).searchParams.get("groupBy")).toBe("vehicle");
});

test("returns the report data once the fetch resolves", async () => {
  mockFetchOnce(REPORT);
  const { result } = renderHook(() => useHgvTollReport("2026-07-01", "2026-07-31"));
  await waitFor(() => expect(result.current.data).not.toBeNull());
  expect(result.current.data).toEqual(REPORT);
  expect(result.current.isLoading).toBe(false);
  expect(result.current.error).toBeNull();
});

test("missing from/to -> no fetch call, data stays null", async () => {
  const { result } = renderHook(() => useHgvTollReport(null, null));
  expect(global.fetch).not.toHaveBeenCalled();
  expect(result.current.data).toBeNull();
  expect(result.current.isLoading).toBe(false);
});

test("a non-ok response surfaces as an error, not a thrown exception", async () => {
  mockFetchOnce({ error: "Bad Request" }, false, 400);
  const { result } = renderHook(() => useHgvTollReport("2026-07-01", "2026-07-31"));
  await waitFor(() => expect(result.current.error).not.toBeNull());
  expect(result.current.data).toBeNull();
  expect(result.current.isLoading).toBe(false);
});

test("changing groupBy re-fetches with the new value", async () => {
  mockFetchOnce(REPORT);
  const { rerender } = renderHook(
    ({ groupBy }: { groupBy: HgvTollGroupBy }) => useHgvTollReport("2026-07-01", "2026-07-31", groupBy),
    { initialProps: { groupBy: "vehicle" } }
  );
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(1));

  mockFetchOnce({ ...REPORT, groupBy: "driver" });
  rerender({ groupBy: "driver" });
  await waitFor(() => expect(global.fetch).toHaveBeenCalledTimes(2));

  const [secondUrl] = (global.fetch as jest.Mock).mock.calls[1];
  expect(new URL(String(secondUrl)).searchParams.get("groupBy")).toBe("driver");
});

test("no auth token -> no fetch call", async () => {
  mockToken = null;
  renderHook(() => useHgvTollReport("2026-07-01", "2026-07-31"));
  expect(global.fetch).not.toHaveBeenCalled();
});
